def count_independent_sets(adj, nodes):
    memo = {}
    def solve(remaining_nodes):
        if not remaining_nodes:
            return 1
        state = tuple(sorted(remaining_nodes))
        if state in memo:
            return memo[state]

        v = remaining_nodes[0]
        # Option 1: v is not in the independent set
        res = solve(remaining_nodes[1:])

        # Option 2: v is in the independent set
        # Then no neighbors of v can be in the independent set
        neighbors_v = adj[v]
        new_remaining = [n for n in remaining_nodes[1:] if n not in neighbors_v]
        res += solve(tuple(new_remaining))

        memo[state] = res
        return res

    return solve(tuple(nodes))

