def solve_ladder(n):
    # Standard ladder graph L_n
    M = [[1, 1, 1], [1, 0, 1], [1, 1, 0]]
    v = [1, 1, 1]
    for i in range(n-1):
        v_next = [0, 0, 0]
        for r in range(3):
            for c in range(3):
                v_next[r] += M[r][c] * v[c]
        v = v_next
    return sum(v)

